css:
@page {
    size: 50mm 30mm;
    margin: 0;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body,
.print-format {
    font-family: 'Arial', 'Helvetica', sans-serif;
    font-size: 8px;
    line-height: 1.2;
    color: #000;
    background: #fff;
    width: 48mm;
    margin: 0 auto;
    padding: 1mm;
}

.barcode-label {
    width: 100%;
    text-align: center;
    padding: 1mm 0;
}

.label-item-name {
    font-size: 8px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    margin-bottom: 1mm;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 46mm;
}

.label-barcode img {
    max-width: 44mm;
    height: 12mm;
    display: block;
    margin: 0 auto;
}

.label-barcode-text {
    font-size: 7px;
    font-family: 'Courier New', monospace;
    letter-spacing: 1px;
    margin-top: 0.5mm;
}

.label-price {
    font-size: 10px;
    font-weight: 900;
    margin-top: 1mm;
}

.label-item-code {
    font-size: 6px;
    color: #555;
}

@media print {

    body,
    .print-format {
        width: 48mm;
        margin: 0;
        padding: 1mm;
    }

    .page-break {
        display: none;
    }
}

html:
{% set label = xpos_item_barcode(doc.item_code, barcode_type="code128", include_qr=False) %}

<div class="barcode-label">
    <div class="label-item-name">{{ doc.item_name }}</div>

    {% if label and label.barcode_uri %}
        <div class="label-barcode">
            <img src="{{ label.barcode_uri }}" alt="{{ label.barcode_value }}" />
        </div>
    {% endif %}

    {% if label and label.price %}
        <div class="label-price">{{ frappe.utils.fmt_money(label.price, currency=label.currency) }}</div>
    {% endif %}

    <div class="label-item-code">{{ doc.item_code }}</div>
</div>
